from fixture import boot,PDF,SERVER
from playwright.async_api import async_playwright,expect
from pathlib import Path
import asyncio,json
H=Path(__file__).parent;ORIGIN='https://tg-app-telo-pomnit.vercel.app/'
async def main():
 results=[]
 async with async_playwright()as pw:
  for engine,width in[('chromium',320),('chromium',390),('chromium',1440),('webkit',320),('webkit',390)]:
   b=await getattr(pw,engine).launch();p=await boot(b,ORIGIN,width);downloads=[];p.on('download',lambda d:downloads.append(d));groups=[]
   p.rights_gate=asyncio.Event();await p.locator('#data-export-pdf').click();await expect(p.locator('#data-export-pdf')).to_have_text('Готовим PDF…');await expect(p.locator('#data-export-pdf')).to_have_attribute('aria-busy','true');await expect(p.locator('#data-rights-close')).to_be_disabled();assert not downloads;groups.append('visible busy state and no automatic file')
   p.rights_gate.set();await p.wait_for_function("!document.querySelector('#data-export-pdf').disabled");await expect(p.locator('#data-export-pdf')).to_have_text('Скачать дневник');await expect(p.locator('#pdf-download-file')).to_be_focused();box=await p.locator('#pdf-download-file').bounding_box();assert box['y']>=0 and box['y']+box['height']<=844
   assert await p.locator('.pdf-ready-panel').evaluate("x=>x.parentElement.id==='data-rights-actions'");assert not downloads;await p.screenshot(path=str(H/f'{engine}-{width}-pdf.png'));groups.append('prepared PDF visible beside source action')
   async with p.expect_download()as info:await p.locator('#pdf-download-file').click()
   d=await info.value;assert d.suggested_filename=='dnevnik-tela.pdf';assert Path(await d.path()).read_bytes()==PDF;groups.append('explicit PDF saves exact bytes')
   await p.locator('.screen--active .data-additional summary').click();opener=p.locator('#data-export-local');await opener.scroll_into_view_if_needed();scroll=await p.evaluate("document.querySelector('#screen-data-rights .screen-scroll').scrollTop");await p.evaluate('Storage.saveHabitualDraft([3,...Array(15).fill(null)])');pending=await p.evaluate('Storage.exportPendingForUser(DataRightsApi.userId)');await opener.click()
   await expect(p.locator('#screen-data-export-preview .screen-title')).to_have_text('Неотправленные записи');await expect(p.get_by_text('Сохранение файла ничего не отправляет.',exact=False)).to_be_visible();local=json.loads(await p.locator('.private-preview-content').text_content());assert {k:v for k,v in local.items()if k!='exportedAt'}=={k:v for k,v in pending.items()if k!='exportedAt'};assert len(downloads)==1
   async with p.expect_download()as info:await p.locator('#private-preview-save').click()
   d=await info.value;assert json.loads(Path(await d.path()).read_text(encoding='utf-8'))==local;groups.append('local copy named and exact explicit save')
   stored=await p.evaluate('privatePreviewReturn');await p.locator('#private-preview-close').click();await expect(opener).to_be_focused();restored=await p.evaluate("document.querySelector('#screen-data-rights .screen-scroll').scrollTop");assert abs(restored-stored['scroll'])<2,{'before':scroll,'stored':stored,'restored':restored};assert await p.locator('.data-additional').evaluate('x=>x.open');groups.append('local return restores opener and place')
   await p.locator('#data-export-json').click();await expect(p.locator('#screen-data-export-preview .screen-title')).to_have_text('Полная копия данных');assert json.loads(await p.locator('pre.private-preview-content').text_content())==SERVER;await p.locator('.screen--active .data-additional summary').click();pre=p.locator('pre.private-preview-content');await pre.focus();await p.keyboard.press('PageDown');await p.wait_for_function("document.querySelector('pre.private-preview-content').scrollTop>0");assert not await p.locator('pre b').count();await p.screenshot(path=str(H/f'{engine}-{width}-copy.png'));groups.append('full copy text intact and keyboard scrollable')
   await p.evaluate('goBack()');await expect(p.locator('#data-export-json')).to_be_focused();groups.append('native return restores full-copy action')
   p.rights_fault='/gdpr/diary.pdf';await p.locator('#data-export-pdf').click();await p.wait_for_function("!document.querySelector('#data-export-pdf').disabled");await expect(p.locator('#data-rights-status')).to_be_focused();await expect(p.locator('#data-rights-status')).to_have_text('Не удалось подготовить файл. Попробуйте ещё раз.');await expect(p.locator('#data-export-pdf')).to_have_text('Скачать дневник');await expect(p.locator('#data-export-pdf')).not_to_have_attribute('aria-busy','true');p.rights_fault=None;await p.locator('#data-export-pdf').click();await expect(p.locator('#pdf-download-file')).to_be_focused();groups.append('failure visible and original action retries')
   await p.locator('#data-delete-start').click();await expect(p.locator('#data-delete-submit')).to_be_disabled();await p.locator('#data-delete-phrase').fill('неверная фраза');await expect(p.locator('#data-delete-submit')).to_be_disabled();await p.locator('#data-delete-cancel').click();await expect(p.locator('#data-delete-confirm')).to_be_hidden();assert not any(method=='DELETE'for method,path in p.rights_calls);groups.append('deletion confirmation stays explicit and cancelled')
   assert not await p.evaluate('document.documentElement.scrollWidth>innerWidth');assert not p.fixture_errors,p.fixture_errors;groups.append('layout and no page errors');results.append({'engine':engine,'width':width,'groups':groups,'syntheticCalls':p.rights_calls,'errors':p.fixture_errors});print(engine,width,'PASS',len(groups),'groups',flush=True);await b.close()
 (H/'ui-results.json').write_text(json.dumps(results,ensure_ascii=False,indent=2),encoding='utf-8')
asyncio.run(main())
